    function remove(id,r){try{sessionStorage.removeItem(prefix+id);if(sessionStorage.getItem(prefix+id)!==null)throw Error('storage');}catch{if(r.stored)return false}records.delete(id);return true}
    release.addEventListener('click',()=>{const id=state.user?.id,r=current();if(!r||r.inFlight)return;if(!confirm('Вы проверили все доступные страницы списка встреч? Встреча могла уже создаться или запрос ещё может выполняться. Если забыть ключ и создать заново, возможен дубль. Завершить проверку?'))return;if(!remove(id,r)){notice('Не удалось удалить сохранённую попытку. Повторите позже; не создавайте встречу заново.');return}render();notice('Проверка завершена. Прежде чем создавать встречу заново, убедитесь, что её нет в списке.')});
